# Executed inside src/build_report.py. E4 prediction intervals; numbers loaded from results/extE4_coverage.csv.
section("Extension E4: prediction intervals")
E4C = "results/extE4_coverage.csv"; SCRIPT[E4C] = "src/ext_E4_intervals.py"
e = []; a = e.append; MN = {"bayes_predictive": "Bayesian predictive", "jackknife_conformal": "jackknife conformal", "constant_gaussian": "constant Gaussian (no predictors)"}
a("### 8.4 E4: Prediction intervals and empirical coverage\n")
a("Math note: `docs/math/E4_prediction_intervals.md`. Three central intervals at 80%, 90% and 95%, evaluated on held-out women: (1) the **Bayesian predictive interval** of E2 (Gaussian); (2) a **jackknife-conformal interval** for ridge, built from the errors of leave-one-woman-out refits inside each training set; (3) a **constant Gaussian reference** (training mean +/- z x training SD, no predictors). Feature sets A (phase), C (phase + hormones), D (C + questionnaires); leave-one-woman-out for the pooled and longitudinal samples, and training on the cross-sectional women with testing on the longitudinal women. Coverage = share of held-out sessions inside the interval, with 95% CIs from resampling women; 'off' = the CI excludes the nominal level.\n")
a(f"Sample sizes (test rows, women): pooled {nn('pooled')}; longitudinal {nn('long')}; cross-sectional to longitudinal: training {nn('cross')}, test {nn('long')}.\n")
cv = lambda s_, t_, f_, m_, l_: val(E4C, dict(sample=s_, target=t_, fset=f_, method=m_, level=l_), "coverage", "{:.2f}", label=f"E4 coverage {s_} {t_} {f_} {m_} {l_}")
wr = lambda s_, t_, f_, m_, l_: val(E4C, dict(sample=s_, target=t_, fset=f_, method=m_, level=l_), "width_ratio_vs_constant", "{:.2f}", label=f"E4 width ratio {s_} {t_} {f_} {m_} {l_}")
for s_ in ["pooled", "long", "cross2long"]:
    a(f"**{SMP[s_].capitalize()} sample** " + (f"(training {nn('cross')}; test {nn('long')})" if s_ == "cross2long" else f"({nn(s_)})") + ". Empirical coverage at the nominal levels 0.80 / 0.90 / 0.95, and mean width at 90% relative to the constant reference (1.00):\n")
    a("| Target | Set | Bayesian predictive | Jackknife conformal | Constant Gaussian | Width at 90% (Bayes / conformal) |\n|---|---|---|---|---|---|")
    for t in TS:
        for f_ in ["A", "C", "D"]:
            a(f"| {TN[t]} | {f_} | " + " | ".join(" / ".join(cv(s_, t, f_, m, l) for l in [0.8, 0.9, 0.95]) for m in MN) + f" | {wr(s_, t, f_, 'bayes_predictive', 0.9)} / {wr(s_, t, f_, 'jackknife_conformal', 0.9)} |")
    a("")
table("T-E4", "empirical coverage and width ratios", E4C, "src/ext_E4_intervals.py")
def cells(s_, m_, extra=""): return agg(E4C, f"sample == '{s_}' and method == '{m_}'{extra}", None, "count", "{:.0f}", label=f"E4 cells {s_} {m_} {extra}")
a("**Where is coverage off?** A cell is one configuration (target x feature set) at one nominal level; 'ok' = the 95% CI of the coverage contains the nominal level, 'under' = the CI lies below it (intervals too narrow), 'over' = above it (too wide):\n")
a("| Sample | Method | cells | ok | under | over |\n|---|---|---|---|---|---|")
for s_ in ["pooled", "long", "cross2long"]:
    for m in MN: a(f"| {SMP[s_]} | {MN[m]} | {cells(s_, m)} | {cells(s_, m, ' and covers_nominal')} | {cells(s_, m, ' and cov_hi < level')} | {cells(s_, m, ' and cov_lo > level')} |")
table("T-E4-off", "counts of cells with coverage on / below / above nominal", E4C, "src/ext_E4_intervals.py")
wd = lambda f_: float(df(E4C).query("sample == 'pooled' and fset == @f_ and method == 'bayes_predictive' and level == 0.9").width_ratio_vs_constant.mean())
mcl = lambda s_, m_, l_: agg(E4C, f"sample == '{s_}' and method == '{m_}' and level == {l_}", "coverage", "median", "{:.3f}", label=f"E4 median coverage {s_} {m_} {l_}")
for m in ["bayes_predictive", "jackknife_conformal"]:
    for l_ in [0.8, 0.9]: claim(float(df(E4C).query(f"sample == 'cross2long' and method == '{m}' and level == {l_}").coverage.mean()) < l_, "cross-sample coverage below nominal")
a(f"\n**Findings.** (1) *Within the same population (leave-one-woman-out) coverage is close to nominal for both the Bayesian and the conformal interval*: median coverage at the 90% level {mcl('pooled', 'bayes_predictive', 0.9)} (Bayesian) and {mcl('pooled', 'jackknife_conformal', 0.9)} (conformal) in the pooled sample, {mcl('long', 'bayes_predictive', 0.9)} and {mcl('long', 'jackknife_conformal', 0.9)} in the longitudinal sample; the cells that are off within these two samples are listed in `results/extE4_coverage.csv` (`covers_nominal == False`). (2) *Across populations coverage is off.* Trained on the cross-sectional women and tested on the longitudinal women, the intervals are too narrow: median coverage at the nominal 80% level {mcl('cross2long', 'bayes_predictive', 0.8)} (Bayesian) and {mcl('cross2long', 'jackknife_conformal', 0.8)} (conformal), at 90% {mcl('cross2long', 'bayes_predictive', 0.9)} and {mcl('cross2long', 'jackknife_conformal', 0.9)}. The same happens to the constant reference interval ({mcl('cross2long', 'constant_gaussian', 0.9)} at 90%), so the cause is the difference between the two samples (the longitudinal women vary more in DRSP, see E2), not the way the interval is built; the conformal guarantee needs exchangeable women. At the 95% level the conformal interval of some cross-sample configurations is conservative (over-coverage, see the table above). (3) *Intervals are only narrower when predictors carry information.* Averaged over targets, the 90% interval is {calc('E4 mean width ratio D bayes pooled', wd('D'), '{:.2f}', E4C, 'mean width_ratio_vs_constant, pooled, set D, Bayesian, 90%')} times the width of the no-predictor interval for set D (pooled), but {calc('E4 mean width ratio A bayes pooled', wd('A'), '{:.2f}', E4C, 'mean width_ratio_vs_constant, pooled, set A, Bayesian, 90%')} for phase alone and {calc('E4 mean width ratio C bayes pooled', wd('C'), '{:.2f}', E4C, 'mean width_ratio_vs_constant, pooled, set C, Bayesian, 90%')} for phase plus hormones: with the same coverage, phase and hormones make the interval practically no narrower, i.e. they do not make the predictions more precise, while the questionnaires do (narrower by {calc('E4 percent narrower D', (1 - wd('D')) * 100, '{:.0f}', E4C, '(1 - mean width ratio) x 100, pooled, set D, Bayesian, 90%')}%). The two methods give very similar widths.\n")
a("**Honest summary.** Intervals for new women from the same study population are well calibrated, but they are wide: the predictions are useful as a rough range, not as a precise forecast, in line with the low R2 of the point predictions. They should not be transferred to women from a different sample without re-calibration.\n")
EXT.append("\n".join(e))
